    "svarFormat": [
      "numeriskt",
      "numeriskt"
    ],
    "ledtrad": "<p>Sätt h(x)=6 och lös gränspunkterna. Parabeln ligger över linjen mellan dem.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true
