    "geogebra": false,
    "svarstyp": "uttryck",
    "rättSvar": "x^6",
    "tolerans": null,
    "självrättning": true,
    "ledtrad": "<p>Multiplicera exponenterna 3 och 2.</p>",
    "traningsniva": 1,
