    "svarstyp": "alternativ",
    "rättSvar": null,
    "tolerans": null,
    "självrättning": true,
    "traningsniva": 1,
    "arbetsinsats": 1,
    "spel": true,
    "ledtrad": "<p>Tecknet på \\(r\\) ger riktningen. Ju närmare \\(|r|\\) är 1, desto starkare är det linjära sambandet.</p>",
    "alternativ": [
      {
        "txt": "Sambandet med r=0,27 är starkare.",
        "ratt": false
      },
      {
        "txt": "Sambandet med r=0,71 är starkare.",
        "ratt": true
      },
      {
        "txt": "Sambanden är lika starka.",
        "ratt": false
      }
    ]
