    "rättSvar": [
      [
        "5",
        "16"
      ],
      "5<=x<=16"
    ],
    "tolerans": [
      [
        0.01,
        0.01
      ],
      0.01
    ],
    "självrättning": true,
    "svarsstruktur": "ordnad",
