    "kurs": [
      "2b",
      "2c"
    ],
    "niva": "E",
    "poang": "2/0/0",
    "t": "<p>Två kordor skär varandra. Den ena delas i 5 cm och 8 cm. Den andra i 4 cm och \\(x\\) cm. Bestäm \\(x\\).</p><span class=\"fig smal\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"460\" height=\"330\" viewBox=\"0 0 460 330\" role=\"img\" aria-label=\"Två kordor som skär varandra i punkten P\">\n<rect x=\"1\" y=\"1\" width=\"458\" height=\"328\" rx=\"12\" fill=\"#fff\" stroke=\"#d8dbe1\"/>\n<circle cx=\"230\" cy=\"165\" r=\"120\" fill=\"none\" stroke=\"#24262b\" stroke-width=\"3\"/>\n<line x1=\"125\" y1=\"105\" x2=\"340\" y2=\"225\" stroke=\"#24262b\" stroke-width=\"3\"/><line x1=\"130\" y1=\"235\" x2=\"335\" y2=\"90\" stroke=\"#24262b\" stroke-width=\"3\"/>\n<circle cx=\"231\" cy=\"164\" r=\"4\" fill=\"#315f9e\"/><text x=\"240\" y=\"154\" font-size=\"18\" font-family=\"Arial\">P</text>\n<text x=\"167\" y=\"128\" font-size=\"17\" fill=\"#315f9e\" font-family=\"Arial\">5</text><text x=\"290\" y=\"205\" font-size=\"17\" fill=\"#315f9e\" font-family=\"Arial\">8</text><text x=\"165\" y=\"216\" font-size=\"17\" fill=\"#315f9e\" font-family=\"Arial\">4</text><text x=\"292\" y=\"121\" font-size=\"17\" fill=\"#315f9e\" font-family=\"Arial\">x</text>\n</svg></span>",
    "s": "<p>\\(5\\cdot8=4x\\Rightarrow x=10\\).</p>",
    "familj": "kordasatsen_biskarningssatsen__direkt",
    "formaga": [
      "procedur"
    ],
    "miniräknare": false,
    "geogebra": false,
