    "rättSvar": 10,
    "tolerans": 1e-09,
    "självrättning": true,
    "ledtrad": "<p>Produkten 5·8 ska vara lika med 4·x.</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "svarFormat": "numeriskt"
