    "arbetsinsats": 1,
    "spel": true,
    "ledtrad": "<p>I en linjär modell anger lutningen förändringen i y när x ökar med 1.</p>",
    "svarstyp": "alternativ",
    "rättSvar": null,
    "tolerans": null,
