    "ledtrad": "<p>Välj normalfördelning och markera arean till vänster om 60.</p>",
    "svarstyp": "numeriskt",
    "rättSvar": 84.1,
    "tolerans": 0.2,
    "självrättning": true,
    "svarFormat": "numeriskt",
